g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "concession-matrix",
  "x": 64, "y": 236, "width": 1152, "height": 300,
  "strict_grid": true,
  "column_widths": [288, 461, 403],
  "row_heights": [48, 84, 84, 84],
  "style": {
    "font_family": "Calibri",
    "font_size": 20,
    "header_fill": "#003657",
    "header_text": "#FBF8F2",
    "body_text": "#1E1E1E",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 16, "right": 16, "top": 6, "bottom": 6},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#D6CFC2", "width": 1},
        "bottom": {"style": "solid", "color": "#D6CFC2", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "Concession", "bold": true, "align": "l"},
    {"text": "Potential benefit", "bold": true, "align": "l"},
    {"text": "Cost or limit", "bold": true, "align": "l"}
  ],
  "rows": [
    [
      {"text": "Commitment option", "bold": true, "color": "#003657"},
      {"text": "Ease funding strain and reduce non-performance risk", "fill": "#F1ECE2"},
      {"text": "Less deployable capital if exercised", "color": "#A33D3D"}
    ],
    [
      {"text": "Fee cut", "bold": true, "color": "#003657"},
      {"text": "Share the burden and support LP confidence", "fill": "#F1ECE2"},
      {"text": "Lower fee revenue", "color": "#A33D3D"}
    ],
    [
      {"text": "Call approval threshold", "bold": true, "color": "#003657"},
      {"text": "Improve cash-planning predictability", "fill": "#F1ECE2"},
      {"text": "Additional approval above the threshold", "color": "#A33D3D"}
    ]
  ]
}
